import{t as e}from"./jsx-runtime-lw2jiZar.js";import{C as t,E as n,M as r,N as i,O as a,P as o,S as s,_ as c,a as l,b as u,j as d,k as f,l as p,n as m,o as h,t as g,u as _,w as v}from"./shared-f6Drw7Sx.js";import{t as y}from"./key-round-D-Q1K68g.js";import{k as b}from"./index-mjLKWsua.js";import{t as x}from"./CodeEditor-BZlrvoTL.js";var S=e();function C({module:e}){return(0,S.jsxs)(i,{children:[(0,S.jsx)(r,{variant:`project`,chip:e??`Месяц 2 · Блок 8`,title:`Сквозная приёмка накопленного проекта`,intro:`Сверим готовый Persistent Planner как единый продукт: от команды до файла и обратно. Приёмка подтвердит совместную работу уже созданных частей, а исправлять будем только воспроизводимые дефекты.`,tags:[{icon:(0,S.jsx)(b,{size:14}),label:`сквозная приёмка`},{icon:(0,S.jsx)(y,{size:14}),label:`состояние и сохранение`}]}),(0,S.jsxs)(o,{number:`00`,title:`От проверенных частей к одному пользовательскому пути`,children:[(0,S.jsx)(a,{children:`К этому шагу по маршруту уже готовы Task, PlannerService, оба storage, тонкий CLI и проверки команд. Теперь мы посмотрим, согласуются ли их результаты в одном сценарии и переживают ли они повторное создание сервиса.`}),(0,S.jsx)(f,{variant:`connected`,items:[{title:`Точка старта`,description:`Мы принимаем существующие модель, сервис, JsonStorage, MemoryStorage, CLI и регрессионные проверки занятия 42.1.`},{title:`Новый вопрос`,description:`Совпадают ли пользовательский ответ, состояние задач и сохранённые данные на успешном и ошибочном пути?`},{title:`Результат`,description:`Мы проводим приёмку на отдельном JSON, восстанавливаем состояние новым сервисом и исправляем только подтверждённый дефект.`}]}),(0,S.jsx)(`p`,{children:`Эти пункты задают проверку целого, а не новый этап сборки проекта. Сначала мы удостоверимся, что фактическая ветка действительно достигла входа занятия. Если Task, JsonStorage, сервис, удаление или нужные проверки отсутствуют, это незавершённая работа предыдущих шагов. Тогда мы запишем конкретный пробел и вернём его к соответствующему занятию, не маскируя его первой реализацией в финальной приёмке.`})]}),(0,S.jsxs)(o,{number:`01`,title:`Что доказывает сквозная приёмка`,children:[(0,S.jsx)(a,{children:`У отдельного компонента и у целой программы разные границы проверки. Тест Task может подтвердить очистку заголовка, а тест storage подтверждает чтение JSON. Ни один из них по отдельности не доказывает, что команда CLI вызывает правильный метод и сохраняет именно изменённый набор.`}),(0,S.jsx)(`p`,{children:`Представим оркестр: мы можем отдельно проверить настройку каждого инструмента, но для звучания пьесы музыкантам ещё нужно вступить в правильном порядке. В Planner роли тоже должны совпасть во времени. CLI разбирает команду и показывает ответ, сервис выполняет предметное действие, Task хранит правила одной задачи, а storage загружает и сохраняет актуальный список. Сквозной сценарий проверяет их сотрудничество.`}),(0,S.jsx)(`p`,{children:`Перед началом мы сверим точку A: прошлые проектные результаты должны существовать в коде, а полный набор тестов должен защищать уже реализованные части. Название занятия или зелёная проверка только одного слоя не заменяют эту сверку. Отсутствующий файл, ожидающий xfail для уже обещанного поведения или отсутствующий delete означают, что вход ещё не готов.`}),(0,S.jsx)(u,{question:`Все тесты Task и storage проходят. Что это уже доказывает?`,options:[`Отдельные правила и границы проверены, но весь путь CLI ещё не подтверждён`,`Любая команда CLI обязательно сохраняет нужное состояние`,`Отдельный процесс уже восстановит тот же список`],correctIndex:0,explanation:`Мы подтверждаем только те границы, которые реально вызвал тест. Пользовательский сценарий нужен, чтобы проверить связи между ними.`})]}),(0,S.jsxs)(o,{number:`02`,title:`Роли объектов в одном сценарии`,children:[(0,S.jsx)(a,{children:`Чтобы искать расхождение, мы сначала проследим путь данных. Схема показывает обычную работу с JsonStorage; MemoryStorage использует тот же договор load/save, но не читает файл.`}),(0,S.jsxs)(g,{caption:`Команда, сервис и путь сохранённых данных`,children:[(0,S.jsxs)(h,{label:`Связь CLI, PlannerService, storage и JSON-файла`,children:[(0,S.jsx)(p,{title:`CLI`,shape:`input-output`}),(0,S.jsx)(m,{label:`вызов и ответ`,direction:`both`}),(0,S.jsx)(p,{title:`PlannerService`}),(0,S.jsx)(l,{forward:`save: сервис → storage`,reverse:`load: storage → сервис`}),(0,S.jsx)(p,{title:`JSON storage`}),(0,S.jsx)(l,{forward:`запись JSON`,reverse:`чтение JSON`}),(0,S.jsx)(p,{title:`JSON-файл`,shape:`database`})]}),(0,S.jsx)(_,{title:`Граница ответственности`,children:(0,S.jsx)(`p`,{children:`Task описывает одну задачу. JSON хранит записи, а не методы. MemoryStorage возвращает и принимает список Task без файла. CLI не выполняет CRUD и не разбирает JSON.`})})]}),(0,S.jsx)(`p`,{children:`Мы читаем схему слева направо. CLI вызывает сервис и получает результат для показа. Сервис загружает текущие Task через storage, применяет действие и при успешном изменении просит сохранить набор. JsonStorage переводит Task в записи и обратно; сервис не знает файловый формат. MemoryStorage может заменить его в тесте, но это отдельный выбранный объект, а не дополнительный кеш.`}),(0,S.jsx)(`p`,{children:`Это похоже на передачу посылки через стойку доставки: оператор принимает запрос, внутренний отдел выполняет работу, а хранилище оформляет и размещает отправление. Стойка не должна сама менять содержимое коробки, а склад не должен разговаривать с клиентом. Аналогия помогает разделить роли, но программа дополнительно передаёт объекты и может показать точную ошибку каждого слоя.`}),(0,S.jsx)(x,{caption:`что мы наблюдаем на каждой границе`,code:`CLI: команда и сообщение
PlannerService: результат действия
Task: id, title, priority, is_done, tags
Storage: актуальный список и факт save
JSON: записи, сохранённые на выбранном пути`})]}),(0,S.jsxs)(o,{number:`03`,title:`Положительный путь через настоящий CLI`,children:[(0,S.jsx)(a,{children:`Один заранее определённый сценарий полезнее набора несвязанных кликов. Мы фиксируем начальное состояние, выполняем известные действия и заранее понимаем, какое сообщение, набор Task и статистику ожидаем.`}),(0,S.jsx)(`p`,{children:`Для контрольного примера мы начинаем с пустого учебного JSON и добавляем две задачи: «Проверить отчёт» и «Собрать версию». Затем просматриваем список, находим задачу по id, ищем фрагмент заголовка, отмечаем первую задачу выполненной, удаляем вторую и запрашиваем статистику. Рабочий data/tasks.json в этом опыте не используется.`}),(0,S.jsx)(`p`,{children:`После удаления должна остаться первая Task с тем же id и статусом выполнения. Сводка должна согласовываться сама с собой: all равно open плюс done. Для этого примера остаётся одна выполненная задача: all = 1, open = 0, done = 1. Сообщение CLI важно, но мы сверяем и сами данные, и файл: успешный текст сам по себе не доказывает успешное сохранение.`}),(0,S.jsx)(`p`,{children:`Чтобы проход можно было повторить, мы задаём отдельный временный путь и передаём его в JsonStorage при сборке сервиса. Перед каждым повтором создаём известное пустое состояние. Это исключает влияние старого учебного файла и защищает рабочие данные. Мы также сверяем путь и повторно читаем запись: иначе команды могут обращаться не к тому storage, который мы проверяем. Так мы подтверждаем настоящее соединение слоёв, а не только похожий вывод.`}),(0,S.jsx)(v,{title:`Восстановим порядок контрольного сценария`,prompt:`Расположите действия от исходного JSON до наблюдаемого итога.`,pieces:[{id:`empty`,code:`пустой учебный JSON`,note:`Мы начинаем с пустого учебного файла.`},{id:`add`,code:`добавить две задачи`,note:`Мы фиксируем созданные id и поля.`},{id:`read`,code:`list → find → search`,note:`Мы убеждаемся, что чтение не меняет файл.`},{id:`change`,code:`done первой → delete второй`,note:`После этих команд у нас остаётся одна завершённая Task.`},{id:`stats`,code:`получить stats`,note:`Мы сверяем all, open и done.`}],correctOrder:[`empty`,`add`,`read`,`change`,`stats`],explanation:`Мы начинаем с известной базы, затем различаем чтение и изменения и только после этого сверяем итоговую сводку.`,incorrectExplanation:`Мы восстановим причинный порядок: сначала зафиксируем исходные данные, затем изменения и в конце ожидаемый результат.`}),(0,S.jsx)(c,{code:`tasks = [
    {"id": 1, "is_done": True},
    {"id": 2, "is_done": False},
]
tasks[0]["is_done"] = True
tasks.pop(1)
all_count = len(tasks)
done_count = sum(task["is_done"] for task in tasks)
open_count = all_count - done_count
print(all_count, open_count, done_count)`,output:`1 0 1`,hint:`Мы сохранили первую запись, завершили её и удалили вторую. Статистика считает оставшийся список, а не число действий.`}),(0,S.jsxs)(n,{tone:`info`,children:[(0,S.jsx)(`strong`,{children:`Что мы подтверждаем.`}),` Список, карточка, поиск, статус, удаление, статистика и JSON согласованы после одного реального пользовательского пути.`]})]}),(0,S.jsxs)(o,{number:`04`,title:`Восстановление новым сервисом`,children:[(0,S.jsx)(a,{children:`После сценария мы отделим сохранённые данные от объекта, который обслуживал команды. Новый PlannerService, созданный с тем же путём JsonStorage, должен заново получить задачу из файла.`}),(0,S.jsx)(`p`,{children:`Новый вызов load() на том же объекте слабее: в нём могут оставаться ссылки или состояние, созданное предыдущим действием. Новый сервис строит свежую цепочку использования storage. Мы снова просматриваем список, статус и сводку, затем проверяем следующий id по принятому правилу: один больше максимального id в текущем наборе. Удаление не перенумеровывает оставшиеся записи; проект не обещает вечную уникальность уже удалённых номеров.`}),(0,S.jsx)(`p`,{children:`Это похоже на то, как мы закрываем рабочую тетрадь и открываем новую копию по сохранённому файлу, вместо того чтобы продолжать смотреть на ту же страницу. Новый сервис проверяет повторное чтение данных, но всё ещё живёт в том же процессе. Отдельный процесс и чистая проверочная копия относятся к следующему занятию, поэтому здесь мы не выдаём одну проверку за другую.`}),(0,S.jsx)(`p`,{children:`Новый экземпляр важен потому, что он проверяет не только повторный вызов load(), но и сборку зависимостей. Мы создаём JsonStorage с прежним путём и передаём его новому PlannerService, не используя прежний список Task. Затем сверяем поля восстановленной задачи и результат stats. После этого добавляем запись и сравниваем её id с договором проекта. Так мы отличаем сохранённые данные от ссылки на объект, которая могла случайно пережить предыдущую команду в памяти.`}),(0,S.jsx)(u,{question:`Что подтверждает новый PlannerService на том же JSON-пути?`,options:[`Что данные снова загружаются через storage, а не берутся из прежнего сервиса`,`Что отдельный процесс и чистый клон уже проверены`,`Что любая неудачная запись автоматически откатила память`],correctIndex:0,explanation:`Новый сервис проверяет повторное чтение на том же пути. Новый процесс и чистая копия дают отдельные доказательства.`})]}),(0,S.jsxs)(o,{number:`05`,title:`Ошибки, состояние и границы гарантий`,children:[(0,S.jsx)(a,{children:`Отказ тоже часть результата. Мы смотрим не только на текст ошибки, но и на то, изменились ли данные и вызывалось ли сохранение.`}),(0,S.jsx)(`p`,{children:`На отдельной копии проверяются неверные значения, неизвестный id, неизвестная команда и повторное завершение. Пользовательская ошибка должна дать понятное сообщение, не менять задачу и не запускать лишний save. Читающая команда тоже не сохраняет данные. Эти ожидания уже должны совпадать с договорами сервиса и CLI, созданными раньше.`}),(0,S.jsx)(`p`,{children:`Отказ storage проверяется отдельно. Повреждённое чтение не превращается в пустой список и не приводит к перезаписи файла. При отказе записи после изменения Task состояние в памяти могло измениться, хотя сохранение не состоялось. Обычная запись через режим w не является транзакцией и сама по себе не откатывается. Поэтому мы ищем сообщение без ложного успеха и проверяем точные факты, не требуя недоступной гарантии.`}),(0,S.jsx)(`p`,{children:`Проверки отказа мы делим по моменту сбоя. Если аргумент не прошёл проверку или id не найден, изменение не должно начинаться: мы сравниваем список до и после и проверяем, что save не вызывался. Если load не разобрал файл, мы сохраняем исходные данные как свидетельство ошибки, не подменяя их пустым проектом. Если запись упала уже после изменения объекта, отдельно фиксируем состояние памяти, ответ CLI и содержимое файла. Эти результаты могут различаться, поэтому каждое утверждение называет именно тот слой, к которому оно относится.`}),(0,S.jsx)(s,{statement:(0,S.jsx)(S.Fragment,{children:`"Если save завершился StorageError, состояние Task в памяти гарантированно вернулось к исходному."`}),isTrue:!1,explanation:`Мы не обещаем автоматический rollback: объект уже мог измениться до вызова storage. Проверяем отдельно состояние памяти и факт успешной записи.`}),(0,S.jsx)(`p`,{children:`Для отказа чтения важна сохранность прежнего файла. Для отказа записи важны отсутствие ложного подтверждения и ясная граница того, что уже изменилось. Смешивать эти случаи общей фразой «данные не изменились» нельзя: она может быть неверной для состояния в памяти.`})]}),(0,S.jsxs)(o,{number:`06`,title:`Локализуем только воспроизводимый дефект`,children:[(0,S.jsx)(a,{children:`Сквозная приёмка может найти ошибку соединения даже при зелёных тестах отдельных частей. Мы повторяем конкретное действие с теми же данными и ищем первую границу, где ожидание расходится с наблюдением.`}),(0,S.jsx)(`p`,{children:`Результат удобно разложить на три независимых наблюдения: ответ CLI, текущее состояние Task и содержимое storage после повторного чтения. Если ответ успеха появился, а новый сервис не видит изменение, мы проверяем, какой storage получил сервис и был ли save. Если ошибка команды изменила список, проверяем, не присвоено ли новое значение до валидации.`}),(0,S.jsx)(t,{code:`# фрагмент: service и storage уже созданы
task = service.get_task(1)
task.mark_done()
restored = storage.load()
assert restored[0].is_done is True`,question:`Почему эта проверка может падать, хотя mark_done изменил Task?`,options:[`Изменение объекта обошло сервисный путь и не было сохранено через service`,`is_done нельзя читать после загрузки JSON`,`Любой load() автоматически сбрасывает все статусы`],correctIndex:0,explanation:`Мы меняем возвращённый объект напрямую. JsonStorage восстановит сохранённое состояние; для прикладного перехода используем service.mark_done(1), который отвечает и за изменение, и за save.`,fix:`service.mark_done(1)
restored = storage.load()
assert restored[0].is_done is True`}),(0,S.jsx)(`p`,{children:`Наблюдение указывает на границу между моделью и прикладным действием: Task изменилась напрямую, а сервис не получил команду сохранить новое состояние. Теперь мы проверим тот же сценарий через метод сервиса.`})]}),(0,S.jsxs)(o,{number:`07`,title:`Узкая правка и регрессионная проверка`,children:[(0,S.jsx)(a,{children:`Мы исправляем только подтверждённую причину. Если путь уже работает и все ожидания совпадают, приёмка заканчивается без искусственного дефекта и косметического переписывания.`}),(0,S.jsx)(`p`,{children:`После воспроизведения мы добавляем минимальную регрессионную проверку, которая сначала падает именно на этом ожидании. Затем исправляем источник несогласованности и повторяем тот же путь вместе с полным набором pytest. Если расхождения нет, мы не придумываем дефект ради коммита и не переписываем исправные компоненты для красоты.`}),(0,S.jsx)(`p`,{children:`Регрессионная проверка должна описывать наблюдаемое требование, а не повторять устройство исправления. После точечной проверки мы повторяем старые команды и сверяем список, поиск, статусы, удаление и статистику, чтобы исправление одного пути не нарушило соседний. Полный pytest подтверждает сохранность прежних договоров проекта. Если весь сценарий изначально совпал с ожиданиями, мы фиксируем результат приёмки без кодового изменения.`}),(0,S.jsx)(x,{caption:`эскиз разбора, не запускаемый код`,code:`повторить точное действие
сверить сообщение, Task и storage
найти первую неверную границу
закрепить наблюдение тестом
исправить причину и повторить сценарий`})]}),(0,S.jsxs)(o,{number:`08`,title:`Что мы будем делать в практике`,children:[(0,S.jsx)(a,{children:`Практика соединит уже изученные роли и проверки. Мы используем действующий Persistent Planner и отдельный учебный JSON; этот шаг не начинает проект с модели или пустого CLI.`}),(0,S.jsx)(f,{variant:`connected`,items:[{title:`Сверим вход`,description:`Мы подтвердим Task, service, оба storage, CLI, удаление и проверки 42.1; недостающие результаты отнесём к предыдущим занятиям.`},{title:`Пройдём сценарий`,description:`Мы выполним add, list, find, search, done, delete и stats; сообщения, поля, статусы и записи должны совпасть.`},{title:`Восстановим данные`,description:`Мы создадим новый service на том же JSON-пути и сверим список, завершённость, сводку и следующий id.`},{title:`Разберём отказы`,description:`Мы проверим ошибки и вызовы save на копии; воспроизводимый дефект получит узкий тест и исправление, а чистый проход не вызовет косметических изменений.`}]}),(0,S.jsx)(`p`,{children:`Схема ролей подготовила нас к выбору места проверки: CLI отвечает за сообщение, сервис за действие, модель за правила Task, storage за актуальные данные. Мы сверим три наблюдения вместе, чтобы успешный вывод не скрыл несохранённое изменение.`}),(0,S.jsx)(`p`,{children:`Новый service подтверждает восстановление через выбранный путь. Отдельный процесс, чистая копия, README и передача проверенной версии остаются следующим шагом. Здесь мы завершаем сквозную приёмку уже готового продукта.`}),(0,S.jsx)(d,{text:`Пройдите сквозной сценарий на учебном JSON и исправьте только воспроизводимое расхождение.`})]})]})}export{C as Lesson43};